import{_ as t,c as n,o as a,ag as r}from"./chunks/framework.Ci10AEOF.js";const u=JSON.parse('{"title":"Security Posture and Hardening","description":"What the engine trusts and exposes as shipped, and the hardening checklist","frontmatter":{"title":"Security Posture and Hardening","description":"What the engine trusts and exposes as shipped, and the hardening checklist"},"headers":[],"relativePath":"engine/security_posture_and_hardening.md","filePath":"engine/security_posture_and_hardening.md","lastUpdated":1793057853000}'),i={name:"engine/security_posture_and_hardening.md"};function o(s,e,d,c,l,h){return a(),n("div",null,e[0]||(e[0]=[r('<h1 id="security-posture-and-hardening" tabindex="-1">Security Posture and Hardening <a class="header-anchor" href="#security-posture-and-hardening" aria-label="Permalink to &quot;Security Posture and Hardening&quot;">​</a></h1><p>For the TLS, authentication and encryption settings, see <a href="./security_and_compliance.html">Security and Compliance</a>.</p><h2 id="customer-code-runs-in-the-server-jvm" tabindex="-1">Customer code runs in the server JVM <a class="header-anchor" href="#customer-code-runs-in-the-server-jvm" aria-label="Permalink to &quot;Customer code runs in the server JVM&quot;">​</a></h2><p>Channel filters, transformers and scripts, code templates, and extensions all run in the server&#39;s JVM with the privileges of the account the server runs as. The JavaScript engine has no sandbox: a script can call any Java class on the server&#39;s classpath.</p><p>A user who can deploy a channel can therefore run code on the host as that account. That code can read the keystore and <code>conf/mirth.properties</code>, reach the database with the engine&#39;s own credentials, change any table, including the ones an authorization extension keeps its roles in, and connect to anything the host can reach. Role separation does not limit a user who can author and deploy channels.</p><h2 id="defaults-often-reported-as-vulnerabilities" tabindex="-1">Defaults often reported as vulnerabilities <a class="header-anchor" href="#defaults-often-reported-as-vulnerabilities" aria-label="Permalink to &quot;Defaults often reported as vulnerabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Status</th><th>What controls it</th></tr></thead><tbody><tr><td>The JavaScript engine runs scripts without a sandbox</td><td>By design</td><td>Who may author and deploy channels</td></tr><tr><td>Every authenticated user may perform every operation</td><td>By design in the core</td><td>An authorization extension such as <a href="https://openintegrationengine.org/plugins/" target="_blank" rel="noreferrer">Role Based Access Control</a>, within the limit above</td></tr><tr><td>The password policy enforces little</td><td>Configuration default</td><td><code>password.minlength</code> ships at <code>15</code>, <code>password.retrylimit</code> at <code>100</code> and <code>password.lockoutperiod</code> at <code>1</code>. Every other <code>password.*</code> key ships at <code>0</code> and enforces nothing. See <a href="./user_management.html#password-policy">User Management</a></td></tr><tr><td>Keystore passwords are stored in <code>conf/mirth.properties</code></td><td>Configuration</td><td>File permissions on the keystore and on <code>conf/mirth.properties</code></td></tr></tbody></table><h2 id="network-placement" tabindex="-1">Network placement <a class="header-anchor" href="#network-placement" aria-label="Permalink to &quot;Network placement&quot;">​</a></h2><p>As shipped, the server listens on:</p><ul><li><code>http.port</code> (8080): the status page, <code>webstart.jnlp</code> and the files the desktop Administrator downloads</li><li><code>https.port</code> (8443): the REST API, which both Administrators log in through</li><li>each deployed channel&#39;s own listener port, on all interfaces unless the channel&#39;s <strong>Local Address</strong> names one</li></ul><p>The engine terminates TLS on its HTTPS port and in the DICOM Listener. The TCP, HTTP and Web Service listeners accept plain connections unless an extension such as <a href="https://github.com/NovaMap-Health/tls-manager-plugin" target="_blank" rel="noreferrer">TLS Manager</a> adds TLS to them (see <a href="./security_and_compliance.html#connector-level-tls">Connector-level TLS</a>). The database holds message content, which in a clinical deployment is PHI.</p><h2 id="dependency-currency" tabindex="-1">Dependency currency <a class="header-anchor" href="#dependency-currency" aria-label="Permalink to &quot;Dependency currency&quot;">​</a></h2><p>Renovate manages dependency updates on the engine repository: a monthly schedule, a 14-day minimum release age, automerge off, and major updates gated behind dependency-dashboard approval. OSV vulnerability alerts are on, so a disclosed vulnerability raises a pull request outside the monthly schedule.</p><p>The build resolves from Maven Central, and Gradle checks every artifact it resolves against a SHA-256 checksum in <code>gradle/verification-metadata.xml</code>, which is committed to the repository. Jars with no byte-identical artifact on Maven Central are committed in the repository&#39;s <code>lib</code> directories instead, and that check does not cover them. Signature verification is off (<code>verify-signatures</code> is <code>false</code>), and the checksums were recorded from the artifacts Gradle first resolved, so the check detects an artifact changing underneath the build, not who published it. Renovate maintains the manifest alongside the updates.</p><p>4.6.0 remediated 24 known CVEs and removed the unmaintained Xerces and xml-apis stack. The source is open under MPL 2.0.</p><h2 id="hardening-checklist" tabindex="-1">Hardening checklist <a class="header-anchor" href="#hardening-checklist" aria-label="Permalink to &quot;Hardening checklist&quot;">​</a></h2><p>The checklist comes down to <strong>FINN</strong>:</p><ul><li><strong>F</strong>irewall the channel listeners to known peers.</li><li><strong>I</strong>nfrastructure carries uptime. OIE runs one server per database, without clustering, so availability comes from a resilient host, database and storage underneath it.</li><li><strong>N</strong>o public IP on the engine.</li><li><strong>N</strong>arrow who can author and deploy channels.</li></ul><ol><li>Run the current release on a patched Java 17 or newer. Security fixes go only into the current minor version, per the engine&#39;s <a href="https://github.com/OpenIntegrationEngine/engine/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>.</li><li>No public IP on the engine. Terminate external traffic at a load balancer, reverse proxy or gateway in front of it, and keep the Administrator and API port on an administrative network.</li><li>Bind channel listeners to specific interfaces, and restrict them by firewall to the peers that send to them.</li><li>Restrict channel authoring and deployment to people trusted with shell access on the host. Role separation is worth configuring for accountability and for limiting accidental damage, but it is not a boundary against someone who can write a channel.</li><li>Enforce a real password policy, or front authentication with a directory service. Apart from <code>password.minlength</code> (<code>15</code>) and the lockout keys, every <code>password.*</code> setting defaults to <code>0</code> and enforces nothing.</li><li>Require TLS 1.2 or later, use mTLS with peers that support it, and restrict the cipher list. For the TCP, HTTP and Web Service connectors these settings come from an extension such as <a href="https://github.com/NovaMap-Health/tls-manager-plugin" target="_blank" rel="noreferrer">TLS Manager</a>.</li><li>Run under a dedicated service account with least privilege. Tighten file permissions on the keystore, properties files, and the appdata directory.</li><li>Use a dedicated database instance, encrypted at rest, with credentials not shared with other applications.</li><li>Set message storage to the minimum content level each channel needs, with a pruning schedule aligned to the retention policy.</li><li>Forward server and channel event logs to a SIEM. Alert on failed logins, channel deploys, and configuration changes.</li><li>Keep channel configuration in version control and review changes like code. The <a href="https://github.com/diridium-com/simple-channel-history" target="_blank" rel="noreferrer">Simple Channel History</a> community extension also keeps a revision of each channel and code template every time it is saved, in the engine&#39;s database. Comparing two revisions always shows a standard side-by-side diff with word-level highlighting, and a component view also breaks them down into their scripts, connectors, filter and transformer steps, and plugin properties, marking each part added, removed, modified or unchanged. Any revision can be restored.</li><li>Scope penetration testing to the deployed configuration.</li></ol><p>Report engine defects as described under <a href="./security_and_compliance.html#reporting-security-vulnerabilities">Reporting security vulnerabilities</a>. See <a href="./data_pruning_and_maintenance.html">Data Pruning and Maintenance</a> for retention settings.</p>',20)]))}const g=t(i,[["render",o]]);export{u as __pageData,g as default};
